import sys, json, random
sys.path.insert(0,'/workspace/t')
from run import run
import ref

TOKENS = [b'GET', b'POST', b'PUT', b'X', b'HTTP/1.1', b'/x', b'/', b'a b', b'', b'Host', b'Host:',
          b'h.example', b'Content-Length: 0', b'Content-Length: 3', b'Content-Length: 3, 3',
          b'Content-Length: 3, 4', b'Content-Length: ', b'Transfer-Encoding: chunked',
          b'Transfer-Encoding: gzip', b'X-T: v', b'X-T:', b': v', b'bad header', b'\r\n',
          b'5\r\nhello\r\n', b'0\r\n\r\n', b'zz\r\n', b'1;x=y\r\n', b'\r', b'\n', b'abc']

def gen(rng, n):
    parts = []
    for _ in range(n):
        parts.append(rng.choice(TOKENS))
        if rng.random() < 0.5:
            parts.append(b'\r\n')
    return b''.join(parts)

def owner_fn(offsets):
    ends = [o[1] for o in offsets]
    import bisect
    def f(start, end):
        spans = []
        i = bisect.bisect_right(ends, start)
        for k in range(i, len(offsets)):
            lo, hi, own = offsets[k]
            if lo >= end: break
            a = max(lo, start); b = min(hi, end)
            if b > a: spans.append((own, b-a))
        order = []; counts = {}
        for lab, c in spans:
            if lab in counts: counts[lab] += c
            else: counts[lab] = c; order.append(lab)
        owner = spans[0][0] if spans else None
        return owner, [[l, counts[l]] for l in order]
    return f

def run_one(seed):
    rng = random.Random(seed)
    data = gen(rng, rng.randint(1, 14))
    if len(data) > 60000: return None
    nparts = rng.randint(1, 3)
    cuts = sorted(rng.sample(range(0, len(data)+1), min(nparts, len(data)+1)))
    bounds = [0]+cuts+[len(data)]
    parts = []
    owners = ['a', None]
    for i in range(len(bounds)-1):
        if bounds[i] == bounds[i+1]:
            parts.append((rng.choice(owners), b''))
        else:
            parts.append((rng.choice(owners), data[bounds[i]:bounds[i+1]]))
    doc = {"seed":"s","definitions":[],"timeout_ms":10,
           "cases":[{"name":"a","frames":[{"Type":"headers","data_to_transfered":[[":method","GET"]],"End_Stream":True}],
                     "expect":{"method":"GET","target":"/x","host":"h.example"}}],
           "events":[],
           "channels":[{"name":"c","parts":[{"case":o,"data":p.decode('latin1')} for o,p in parts]}]}
    out = run(doc)
    if 'error' in out:
        return ('INPUT_ERROR', data, parts, None)
    ch = out['channels'][0]
    # reference
    offsets = []
    pos = 0
    for o,p in parts:
        offsets.append((pos, pos+len(p), o)); pos += len(p)
    try:
        recs = ref.parse_all(data, owner_fn(offsets))
        err = None
    except ref.Syntax:
        recs = None; err = 'syntax'
    except ref.Incomplete:
        recs = None; err = 'incomplete'
    got = ch['requests']
    if recs is None:
        if ch['error'] is None or ch['error']['kind'] != err:
            return ('MISMATCH_ERR', data, parts, (ch['error'], err))
        return None
    if ch['error'] is not None:
        return ('MISMATCH_ERR2', data, parts, (ch['error'], err))
    if len(got) != len(recs):
        return ('MISMATCH_COUNT', data, parts, (len(got), len(recs)))
    for g, r in zip(got, recs):
        for key in ('start','end','method','target','host','host_count','headers','body','trailers','framing','owner','owners'):
            if g[key] != r[key]:
                return ('MISMATCH_FIELD:'+key, data, parts, (g[key], r[key]))
    if ch['bytes'] != ref.fp(data):
        return ('MISMATCH_BYTES', data, parts, (ch['bytes'], ref.fp(data)))
    return None

bad = 0
for seed in range(4000):
    r = run_one(seed)
    if r:
        bad += 1
        print('FAIL seed', seed, r[0])
        print('  data', r[1][:200])
        print('  parts', r[2][:3])
        print('  detail', str(r[3])[:300])
        if bad > 4: break
print('done, failures:', bad)
